"""Offline integrity/heading audit; never feeds truth or future state to the node."""
from pathlib import Path
import json,math,sys,numpy as np,pandas as pd
R=Path(__file__).resolve().parent

def main(name):
 p=R/'results/experiment/runs'/name;s=json.loads((p/'physical_start.json').read_text());cap=s['yaw_reference_capture'];ep=json.loads((p/'diagnostic_epoch.json').read_text())['epoch'];a=json.loads((p/'initialization_admission.json').read_text());commands=[json.loads(x) for x in (p/'commands_causal.jsonl').read_text().splitlines()];pre=[x for x in commands if 45<=x['elapsed']<48];desired=math.pi/2-cap['captured_yaw_rad'];delta=np.array([math.atan2(math.sin(x['actual_yaw']-desired),math.cos(x['actual_yaw']-desired)) for x in pre]);obs=[json.loads(x) for x in (p/'deployable_observations.jsonl').read_text().splitlines()];win=[x for x in obs if 45<=x['elapsed']<48];mat=np.array([x['R_flu_enu'] for x in win]);yaw=np.unwrap(np.arctan2(mat[:,1,0],mat[:,0,0]));buckets=[x['source_bucket'] for x in obs]
 c=pd.read_csv(p/'clock_audit.csv');c=c[c.stage==1];idx=max(0,np.searchsorted(c.generation_monotonic_ns.to_numpy(),a['completed_monotonic_ns'],side='right')-1);physical=float(c.sim_upper_s.iloc[idx]-ep)
 columns=['t','stage','base_link_qw','base_link_qx','base_link_qy','base_link_qz'];chunks=[q[(q.stage==1)&(q.t>=ep+45)&(q.t<ep+48)] for q in pd.read_csv(p/'truth_diagnostic.csv',usecols=columns,chunksize=25000)];truth=pd.concat(chunks);w,x,y,z=truth[['base_link_qw','base_link_qx','base_link_qy','base_link_qz']].to_numpy().T;tyaw=np.unwrap(np.arctan2(2*(w*z+x*y),1-2*(y*y+z*z)));aligned=np.interp([v['position_sample_time_s'] for v in win],truth.t.to_numpy(),tyaw);offset=np.arctan2(np.sin(yaw-aligned),np.cos(yaw-aligned))
 quality=[x for x in obs if 18<=x['elapsed']<=34];gap=max(b['t']-a['t'] for a,b in zip(quality,quality[1:]));checks=dict(capture_from_received=cap['source_attitude']['receive_monotonic_ns']<=cap['capture_monotonic_ns'],source_sample_not_after_publish=cap['source_attitude']['source_sample_us']<=cap['source_attitude']['source_publish_us'],command_matches_captured_yaw=bool(len(delta) and np.max(abs(delta))<1e-7),no_truth_integral_reset=not cap['truth_used'] and not cap['integrals_modified'],causal_observations=all(t['receive_monotonic_ns']<=v['receive_cutoff_monotonic_ns'] for v in obs for t in v['stream_timing'].values()),unique_monotone_buckets=len(buckets)==len(set(buckets)) and bool((np.diff(buckets)>0).all()),data_gate=len(quality)>=280 and gap<=.121,clock_deadline=physical<48.8)
 out=dict(run=name,integrity_passed=all(checks.values()),checks=checks,capture=cap,command_yaw_max_error_rad=float(max(abs(delta))),estimated_yaw_mean_deg=float(np.rad2deg(yaw.mean())),true_world_yaw_mean_deg=float(np.rad2deg(tyaw.mean())),estimated_minus_true_yaw_deg=dict(mean=float(np.rad2deg(offset.mean())),std=float(np.rad2deg(offset.std())),last_minus_first=float(np.rad2deg(offset[-1]-offset[0]))),observations=len(quality),max_source_gap_s=gap,online_elapsed=a['completed_elapsed'],native_clock_elapsed=physical,clock_lag_s=physical-a['completed_elapsed'],initialization_passed=a['passed'])
 (R/'results'/f'{name}_integrity.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2));return out['integrity_passed']
if __name__=='__main__':raise SystemExit(0 if main(sys.argv[1]) else 1)
